'
    /Skipping the try tests in the rest of Configure as no targethost was defined when cross-compiling/ {
      print
      print "         run=:"
      print "         to=:"
      print "         from=:"
      print "         ;;"
      skip=1
      next
    }
    skip {
      if ($0 ~ /^       ;;/) skip=0
      next
    }
    { print }
  '

'
    /if \$sh -c "\$run \.\/try / {
      print " if true; then"
      getline
      print " xxx=Ok"
      next
    }
    { print }
  '
